//! Regression guards for the 2026-07-05 remediation arc R5.2 (epic
//! pf-8iji, pf-6naq, ADR-0126): the fixed-cap `(mag*23/16).min(4096)`
//! series-boost idiom UNDERSHOOTS once the realised cancellation exceeds
//! the cap. The peak partial term of each cancelling series is
//! `~2^{|x|*log2 e}`; past the cap the working precision is too low, the
//! Ziv half-width model goes unsound, and `ziv_round` certifies a WRONG
//! value. The fix (ADR-0126) returns the series' largest-partial-term
//! `op_scale` and drives the working precision by the realised
//! cancellation via `cancellation_boosted`, uniform with R5.1 (pf-1vzg).
//!
//! Each kernel gets a DEEP row (the pre-fix kernel certifies wrong) and a
//! SHALLOW control (already correct, and stays so). `i0` is a NO-CHANGE
//! control: `bessel_i`'s recurrence is all-positive (no cancellation), so
//! it was audited and left unchanged; the row proves it was never wrong.
//!
//! Oracles: mpmath 1.4.1, on the BIT-IDENTICAL input (integer, or the
//! exact dyadic `mantissa * 2^exp` for the near-zero J row), rounded to
//! `target` bits. Generators: `scratchpad/gen_r52_oracles.py`,
//! `scratchpad/gen_r52_besselj.py`.
//!
//! All rows are high-target (2900-6000 bits) and heavy, so the whole file
//! is release-gated; the CI MPFR full-union job (`--release`) exercises
//! it. Run: `cargo test --release --features
//! std,big,specials,integrals,bessel,airy,zeta
//! --test regression_review_2026_07_05_r52`.

#![cfg(all(
    feature = "big",
    feature = "specials",
    feature = "integrals",
    feature = "bessel",
    not(debug_assertions)
))]

use core::cmp::Ordering;

use pfloat::{BigFloat, RoundingMode};

const NE: RoundingMode = RoundingMode::NearestEven;

/// Reconstruct the exact dyadic `mantissa * 2^exp2` bit-for-bit (the R5.1
/// idiom): the mantissa is an integer that fits in `prec` bits, so
/// `parse_str` holds it exactly and `scale_by_pow2` only shifts.
fn dyadic(mantissa: &str, exp2: i64, prec: u32) -> BigFloat {
    let (m, pst) = BigFloat::parse_str(mantissa, prec, NE).unwrap();
    assert!(
        pst.is_ok(),
        "mantissa integer must parse exactly at {prec} bits"
    );
    let (x, sst) = m.scale_by_pow2(exp2);
    assert!(sst.is_ok(), "scale_by_pow2 is exact");
    x
}

/// `got` bit-identical to the mpmath dyadic oracle `man * 2^exp` at `p`.
fn assert_dyadic(label: &str, got: &BigFloat, man: &str, exp: i64, p: u32) {
    let expected = dyadic(man, exp, p);
    assert_eq!(
        got.total_cmp(&expected),
        Ordering::Equal,
        "{label}: got {got}, want {expected}"
    );
}

/// erf_deep_x64: erf Maclaurin peak-term cancellation ~x^2 log2 e
#[test]
fn erf_deep_x64() {
    let x = BigFloat::try_from_i64_exact(64, 6000).unwrap();
    let (r, st) = x.erf_round(6000, NE).unwrap();
    assert_dyadic("erf_deep_x64", &r, "", -6000, 6000);
    assert!(st.inexact());
}
/// erf_shallow_x40: erf Maclaurin peak-term cancellation ~x^2 log2 e
