/// besselj_miller_deep: middle-regime Miller near-zero J_0 (proximity D~4998,
/// e_x=6). Miller has no truncation floor, so cancellation_boosted
/// resolves any depth. Old fixed cap undershot D past ~1300 (pf-1vzg family
/// one regime in from the asymptotic).
#[test]
fn besselj_miller_deep() {
    let x = dyadic("", -4992, 5000);
    let (r, st) = x.j0_round(53, NE).unwrap();
    assert_dyadic("besselj_miller_deep", &r, "1197809515255001", -5048, 53);
    assert!(st.inexact());
}
/// besselj_miller_shallow: middle-regime Miller near-zero J_0 (proximity D~250,
/// e_x=6). Miller has no truncation floor, so cancellation_boosted
/// resolves any depth. Old fixed cap undershot D past ~1300 (pf-1vzg family
/// one regime in from the asymptotic).
#[test]
fn besselj_miller_shallow() {
    let x = dyadic(
        "441285280809797517230777673571975152771488833969958443769890061520651317483",
        -241,
        250,
    );
    let (r, st) = x.j0_round(53, NE).unwrap();
    assert_dyadic("besselj_miller_shallow", &r, "7756260990406275", -303, 53);
    assert!(st.inexact());
}
